## My answer to the prompt

A simple MVVM implementation can use `AVAudioRecorder` for recording and its metering API to drive a live level display. The bars below visualize loudness, not separate frequency bands.

```swift
import AVFoundation
import SwiftUI

@MainActor
final class VoiceRecorderViewModel: ObservableObject {
    @Published private(set) var isRecording = false
    @Published private(set) var audioPower: Float = -60
    @Published private(set) var recordingURL: URL?
    @Published var errorMessage: String?

    private var recorder: AVAudioRecorder?
    private var meterTimer: Timer?

    func startRecording() {
        AVAudioSession.sharedInstance().requestRecordPermission { [weak self] granted in
            DispatchQueue.main.async {
                guard let self else { return }
                guard granted else {
                    self.errorMessage = "Microphone access is required to record."
                    return
                }
                self.beginRecording()
            }
        }
    }

    private func beginRecording() {
        do {
            let session = AVAudioSession.sharedInstance()
            try session.setCategory(.record, mode: .default)
            try session.setActive(true)

            let directory = FileManager.default.urls(
                for: .documentDirectory, in: .userDomainMask
            )[0]
            let url = directory.appendingPathComponent(
                "Recording-\(UUID().uuidString).m4a"
            )

            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44_100,
                AVNumberOfChannelsKey: 1,
                AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
            ]

            let newRecorder = try AVAudioRecorder(url: url, settings: settings)
            newRecorder.isMeteringEnabled = true
            newRecorder.prepareToRecord()

            guard newRecorder.record() else {
                throw NSError(
                    domain: "VoiceRecorder",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "Could not start recording."]
                )
            }

            recorder = newRecorder
            recordingURL = nil
            isRecording = true
            startMetering()
        } catch {
            errorMessage = error.localizedDescription
            try? AVAudioSession.sharedInstance().setActive(false)
        }
    }

    private func startMetering() {
        meterTimer?.invalidate()
        meterTimer = Timer.scheduledTimer(withTimeInterval: 0.08, repeats: true) {
            [weak self] _ in
            guard let self, let recorder = self.recorder else { return }
            recorder.updateMeters()
            self.audioPower = recorder.averagePower(forChannel: 0)
        }
    }

    func stopRecording() {
        guard isRecording else { return }

        meterTimer?.invalidate()
        meterTimer = nil

        recordingURL = recorder?.url
        recorder?.stop()
        recorder = nil
        isRecording = false
        audioPower = -60

        do {
            try AVAudioSession.sharedInstance().setActive(
                false,
                options: .notifyOthersOnDeactivation
            )
        } catch {
            errorMessage = error.localizedDescription
        }
    }
}

struct VoiceRecorderView: View {
    @StateObject private var viewModel = VoiceRecorderViewModel()

    private var normalizedLevel: CGFloat {
        CGFloat(min(1, max(0, (viewModel.audioPower + 60) / 60)))
    }

    var body: some View {
        VStack(spacing: 32) {
            Text("Voice Recorder")
                .font(.title)

            HStack(alignment: .center, spacing: 8) {
                ForEach(0..<7, id: \.self) { index in
                    let variation = CGFloat(
                        0.35 + 0.65 * abs(sin(Double(index) * 1.4))
                    )
                    let height = max(
                        6,
                        80 * normalizedLevel * variation
                    )

                    Capsule()
                        .fill(viewModel.isRecording ? .blue : .gray)
                        .frame(width: 10, height: height)
                        .animation(.easeOut(duration: 0.08), value: height)
                }
            }
            .frame(height: 90)

            HStack(spacing: 16) {
                Button("Start Recording") {
                    viewModel.startRecording()
                }
                .disabled(viewModel.isRecording)

                Button("Stop Recording") {
                    viewModel.stopRecording()
                }
                .disabled(!viewModel.isRecording)
            }
            .buttonStyle(.borderedProminent)

            if let url = viewModel.recordingURL {
                Text("Saved: \(url.lastPathComponent)")
                    .font(.caption)
            }

            if let message = viewModel.errorMessage {
                Text(message)
                    .foregroundStyle(.red)
                    .font(.caption)
            }
        }
        .padding()
        .onDisappear {
            viewModel.stopRecording()
        }
    }
}
```

